/bin/bash -lc "curl -fsSL 'https://developers.openai.com/api/reference/resources/responses/methods/create' -o /tmp/openai-responses-doc.html && python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
class Text(HTMLParser):
    def handle_data(self, data):
        text = data.strip()
        if text and any(word in text.lower() for word in ('store', 'input', 'authorization', '/v1/responses', 'output_text')):
            print(text[:1200])
Text().feed(Path('/tmp/openai-responses-doc.html').read_text())
PY"

